-- RAS task manager – Supabase schema.
-- Run once in Supabase Dashboard → SQL Editor → New query → Run. Safe to re-run.
--
-- Every row belongs to the signed-in user (user_id) and Row Level Security
-- restricts all access to the owner, so the public publishable key alone
-- cannot read or change anything.
-- Deletes are soft (deleted_at) so they propagate to devices that were offline.
-- Ids are generated by the app; there are no foreign keys between tables so
-- rows can arrive in any order during sync.

create table if not exists public.clients (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null default '',
  category text not null default 'lead' check (category in ('big', 'small', 'lead')),
  status text not null default '',
  status_updated_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, id)
);

create table if not exists public.projects (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  client_id text not null,
  name text not null default '',
  closed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, id)
);

create table if not exists public.tasks (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  client_id text,
  project_id text,
  description text not null default '',
  done boolean not null default false,
  due_date date,
  stuck_with_id text not null default 'me',
  stuck_reason text not null default '',
  reminder_date date,
  reminder_time text,
  reminder_fired_for text,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, id)
);

create table if not exists public.meeting_topics (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  meeting_date date not null,
  topic text not null default '',
  client_id text,
  project_id text,
  with_whom_id text not null default 'me',
  background text not null default '',
  discussed boolean not null default false,
  decision text not null default '',
  converted_task_id text,
  reminder_date date,
  reminder_time text,
  reminder_fired_for text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, id)
);

-- The "אצל מי זה תקוע" list.
create table if not exists public.people (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null default '',
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (user_id, id)
);

create table if not exists public.app_settings (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  me_id text not null default 'me',
  webhook_url text not null default '',
  webhook_sync_data boolean not null default false,
  webhook_send_reminders boolean not null default false,
  updated_at timestamptz not null default now()
);

-- ---------- Row Level Security: each user sees only their own rows ----------

do $$
declare
  t text;
begin
  foreach t in array array['clients', 'projects', 'tasks', 'meeting_topics', 'people', 'app_settings'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "owner_all" on public.%I', t);
    execute format(
      'create policy "owner_all" on public.%I for all to authenticated
         using (user_id = (select auth.uid()))
         with check (user_id = (select auth.uid()))',
      t
    );
  end loop;
end $$;

-- ---------- Realtime: push row changes to the other open devices ----------

do $$
declare
  t text;
begin
  foreach t in array array['clients', 'projects', 'tasks', 'meeting_topics', 'people', 'app_settings'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
